-- Hyprland injects its Lua API into the host environment.
local hl = rawget(_G, "hl")
local configHome = os.getenv("XDG_CONFIG_HOME") or (os.getenv("HOME") .. "/.config")
-- Generated by NixOS
local vars = dofile(configHome .. "/hypr/vars.lua")
local theme = vars.theme
local geometry = theme.geometry
local mode = theme.defaultMode
local stateHome = os.getenv("XDG_STATE_HOME") or (os.getenv("HOME") .. "/.local/state")
local modeFile = io.open(stateHome .. "/desktop-theme/mode", "r")
if modeFile then
    local savedMode = modeFile:read("*l")
    modeFile:close()
    if theme.palettes[savedMode] then
        mode = savedMode
    end
end
local palette = theme.palettes[mode]

hl.on("hyprland.start", function()
    hl.exec_cmd(vars.shellCommand)
end)

hl.monitor({ output = "", mode = "preferred", position = "auto", scale = "auto" })
-- Keep the display helper's live layout through reloads, including a closed lid.
-- Otherwise the fallback rule re-enables the laptop and steals a workspace.
local runtimeDir = os.getenv("XDG_RUNTIME_DIR")
local instance = os.getenv("HYPRLAND_INSTANCE_SIGNATURE")
if runtimeDir and instance then
    local monitorRules = loadfile(runtimeDir .. "/hypr/" .. instance .. "/desktop-monitors.lua")
    if monitorRules then
        monitorRules()
    end
end
hl.config({
    misc = {
        font_family = theme.fonts.ui,
        -- Use the saved theme while Quickshell loads the wallpaper.
        disable_hyprland_logo = true,
        disable_splash_rendering = true,
        background_color = palette.background,
    },
    binds = {
        -- Alt navigation and window moves stay on the current monitor.
        window_direction_monitor_fallback = false,
        movefocus_cycles_fullscreen = true,
    },
    input = {
        kb_layout = vars.keyboardLayout .. ",us",
        kb_variant = ",intl",
    },
    general = {
        layout = "dwindle",
        -- The bar reserves its own height; use equal gaps on every edge.
        gaps_out = {
            top = geometry.windowGap,
            right = geometry.windowGap,
            bottom = geometry.windowGap,
            left = geometry.windowGap,
        },
        gaps_in = geometry.windowGap / 2,
        border_size = geometry.windowBorder,
        col = {
            active_border = palette.accent,
            inactive_border = palette.outline,
        },
    },
    dwindle = { preserve_split = true },
    decoration = {
        rounding = geometry.windowRadius,
        rounding_power = geometry.roundingPower,
        shadow = {
            enabled = true,
            range = 18,
            render_power = 3,
            color = "#00000033",
            offset = { 0, 3 },
        },
        blur = { enabled = true, size = 8, passes = 4 },
    },
})

-- Keep the top bar stationary when the shell reloads.
hl.layer_rule({
    name = "quickshell-bar",
    match = { namespace = "^quickshell-bar$" },
    no_anim = true,
    blur = true,
    -- Blur the glass fill, but not the faint shadow around it (alpha <= 0.18).
    ignore_alpha = 0.2,
})

-- The menu owns its fade and tile animations.
hl.layer_rule({
    name = "quickshell-settings",
    match = { namespace = "^quickshell-(settings|audio|brightness|system|battery|connections|displays)$" },
    no_anim = true,
})

hl.bind("SUPER + Return", hl.dsp.exec_cmd("ghostty"))
hl.bind("SUPER + B", hl.dsp.exec_cmd("firefox"))
hl.bind("SUPER + comma", hl.dsp.exec_cmd("quickshell ipc call settings toggle"))
hl.bind("SUPER + space", hl.dsp.exec_cmd("hyprctl switchxkblayout all next"))
hl.bind("SUPER + Q", hl.dsp.window.close())
hl.bind("SUPER + SHIFT + E", hl.dsp.exit())
hl.bind("SUPER + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind("SUPER + F", hl.dsp.window.fullscreen({ action = "toggle", mode = "fullscreen" }))
hl.bind("ALT + backslash", hl.dsp.layout("togglesplit"))

-- Laptop media keys also work while locked; only level changes repeat.
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"), { locked = true })
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"), { locked = true })
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { repeating = true, locked = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"), { repeating = true, locked = true })
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("desktop-brightness step 5 && quickshell ipc call brightness refresh"), { repeating = true, locked = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("desktop-brightness step -5 && quickshell ipc call brightness refresh"), { repeating = true, locked = true })

for _, direction in ipairs({
    { key = "H", direction = "l", x = -40, y = 0 },
    { key = "J", direction = "d", x = 0, y = 40 },
    { key = "K", direction = "u", x = 0, y = -40 },
    { key = "L", direction = "r", x = 40, y = 0 },
}) do
    hl.bind("ALT + " .. direction.key, hl.dsp.focus({ direction = direction.direction }))
    hl.bind("ALT + SHIFT + " .. direction.key, hl.dsp.window.move({ direction = direction.direction }))
    hl.bind("ALT + CTRL + " .. direction.key,
        hl.dsp.window.resize({ x = direction.x, y = direction.y, relative = true }), { repeating = true })

    -- Monitor selectors require l/r/u/d, not the full direction names.
    hl.bind("SUPER + " .. direction.key, hl.dsp.focus({ monitor = direction.direction }))
    hl.bind("SUPER + SHIFT + " .. direction.key, hl.dsp.workspace.move({ monitor = direction.direction }))
    hl.bind("SUPER + CTRL + " .. direction.key,
        hl.dsp.window.move({ monitor = direction.direction, follow = true }))
end

for workspace = 1, 10 do
    local key = workspace % 10
    -- One global set: selecting a workspace follows it to its owning monitor.
    hl.bind("SUPER + " .. key, hl.dsp.focus({ workspace = workspace, on_current_monitor = false }))
    hl.bind("SUPER + SHIFT + " .. key, hl.dsp.window.move({ workspace = workspace, follow = true }))
end

hl.bind("SUPER + Tab", hl.dsp.focus({ workspace = "previous" }))
hl.bind("SUPER + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind("SUPER + mouse_up", hl.dsp.focus({ workspace = "e-1" }))

hl.bind("SUPER + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind("SUPER + mouse:273", hl.dsp.window.resize(), { mouse = true })
